`timescale 1ps / 1ps

module PH1P_PHY_HR_PAD (
        ipad,
        opad,
        bpad,
        rst,
        ce,
        isclk,
        ipclk,
        osclk,
        opclk,
        ts,
        doq,
        di,
        diq,
        odly_in,
        odly_out,
        idly_in,
        in_dly,
        out_dly,
        pdr,
        dl_tdi,
        dl_tdo,
        diff_in,
        diff_out,
        rdiff_enb,
        te_n,
        lb_enb,
        ck_dl_o,
        dl_ck_o,
        rst_align
);
input            idly_in;
input            odly_in;
input            dl_tdi;   //[tag:hardwire]
output           dl_tdo;   //[tag:hardwire]
output           odly_out;
input            ipad;
output           opad;
inout            bpad;
input            rst;      //[tag:reset]
input            ce;
input            isclk;    //[tag:clk]
input            ipclk;    //[tag:clk]
input            osclk;    //[tag:clk]
input            opclk;    //[tag:clk]
input            ts;
input  [9:0]     doq;
output           di;
output [9:0]     diq;
input  [7:0]     in_dly;
input  [7:0]	 out_dly;
input            diff_in;  //[tag:virtual]
output           diff_out; //[tag:virtual]
input            rdiff_enb;
input            pdr;
input            te_n;
input            lb_enb;
output           ck_dl_o;
output           dl_ck_o;
input            rst_align;

tri1            rst;
tri1            ce;
tri1            isclk;
tri1            ipclk;
tri1            osclk;
tri1            opclk;
tri1            ts;
tri1  [9:0]     doq;
tri1  [7:0]     in_dly;
tri1  [7:0]     out_dly;
tri1            pdr;
tri1            te_n;
tri1            lb_enb;
